import Link from "next/link";
import { ArrowRightIcon } from "./icons";

/**
 * Editorial section heading.
 *
 * `basis` states why these events are here — "soonest first", "within 25 km
 * of Pune". Sections are generated by real queries, and saying so keeps a
 * rail from reading as a recommendation the product doesn't make.
 */
export default function SectionHead({
  index,
  title,
  basis,
  href,
  linkLabel = "See all",
  id,
}: {
  index: number;
  title: string;
  basis?: string;
  href?: string;
  linkLabel?: string;
  id?: string;
}) {
  return (
    <div className="section-head">
      <span className="section-index numeric" aria-hidden="true">
        {String(index).padStart(2, "0")}
      </span>
      <div className="section-heading-group">
        <h2 className="section-title" id={id}>
          {title}
        </h2>
        {basis && <p className="section-basis">{basis}</p>}
      </div>
      {href && (
        <Link href={href} className="section-link">
          {linkLabel}
          <ArrowRightIcon size={14} />
        </Link>
      )}
    </div>
  );
}
